static bool up_txempty(struct uart_dev_s *dev)
{
  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
  uint32_t isr = up_serialin(priv, STM32_USART_ISR_OFFSET);

#ifdef HAVE_RS485
  if (priv->rs485_dir_gpio != 0)
